export function isReservedDeviceName(name: string): boolean {
	return /^(?:con|prn|aux|nul|com[1-9]|lpt[1-9])$/i.test(name);
}

export function safeWindowsFileName(name: string): string {
	if (isReservedDeviceName(name)) {
		return `_${name}`;
	}
	return name;
}

