import { expect, test } from "bun:test";
import { mkdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { isReservedDeviceName, safeWindowsFileName } from "./platform.js";

test("safeWindowsFileName remaps reserved names and leaves others unchanged", () => {
	expect(safeWindowsFileName("CON")).toBe("_CON");
	expect(isReservedDeviceName(safeWindowsFileName("CON"))).toBe(false);
	expect(safeWindowsFileName("nul")).toBe("_nul");
	expect(safeWindowsFileName("readme")).toBe("readme");
});

test.skipIf(process.platform !== "win32")(
	"safeWindowsFileName returned name can be created on Windows when the original reserved name cannot",
	() => {
		const dir = join(tmpdir(), `flow-safe-win-${Date.now()}`);
		mkdirSync(dir, { recursive: true });
		try {
			const original = "CON";
			const safe = safeWindowsFileName(original);
			expect(safe).not.toBe(original);

			let originalFailed = false;
			try {
				writeFileSync(join(dir, original), "x");
			} catch {
				originalFailed = true;
			}
			expect(originalFailed).toBe(true);

			writeFileSync(join(dir, safe), "x");
		} finally {
			rmSync(dir, { recursive: true, force: true });
		}
	},
);
